SELECT ProductId, SUM(Amount) AS Total
FROM Sales
_____ ProductId;

WITH x AS (
 SELECT *, ROW_NUMBER() OVER(PARTITION BY BusinessKey ORDER BY UpdatedAt DESC) rn
 FROM Source
)
SELECT * FROM x WHERE rn = 1;

SELECT f.OrderId, d.CustomerKey, f.Amount
FROM StgFact f
LEFT JOIN DimCustomer d ON f.CustomerCode=d.CustomerCode;

SELECT OrderId, Amount
FROM Sales
WHERE OrderDate >= '2026-11-01';

SELECT Region, COUNT(*) AS Orders, AVG(Amount) AS AvgAmount
FROM Sales
GROUP BY Region;

SELECT region, SUM(amount) AS total
FROM Sales
GROUP BY region;

SELECT c.id, COUNT(o.order_id) AS orders
FROM Customers c LEFT JOIN Orders o ON c.id=o.customer_id
GROUP BY c.id;

WITH ranked AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY updated_at DESC) AS rn
  FROM Changes
)
SELECT * FROM ranked WHERE rn=1;
